    W = len(grid[0])

    # Main line color
    counts = {}
    for row in grid:
        for v in row:
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
    line = max(counts, key=counts.get)

    # Detect separator rows/cols (the thick grid lines)
    sep_rows = [r for r in range(H) if sum(1 for x in grid[r] if x == line) > W // 2]
    sep_cols = [c for c in range(W) if sum(1 for r in range(H) if grid[r][c] == line) > H // 2]

    R = len(sep_rows) + 1
    C = len(sep_cols) + 1

    row_set = set(sep_rows)
    col_set = set(sep_cols)

    def row_band(r):
        k = 0
        for sr in sep_rows:
            if sr < r:
                k += 1
            else:
                break
        return k

    def col_band(c):
        k = 0
        for sc in sep_cols:
            if sc < c:
                k += 1
            else:
                break
        return k

    # Build graph of cell connectivity through missing line segments
    n = R * C
    adj = [[] for _ in range(n)]

    def cell_id(i, j):
        return i * C + j

    # Vertical separator gaps connect left/right cells within each row band
    for j, sc in enumerate(sep_cols):
        for i in range(R):
            r0 = 0 if i == 0 else sep_rows[i - 1] + 1
            r1 = H - 1 if i == len(sep_rows) else sep_rows[i] - 1
            open_gap = any(grid[r][sc] == 0 for r in range(r0, r1 + 1))
            if open_gap:
                a = cell_id(i, j)
                b = cell_id(i, j + 1)
                adj[a].append(b)
                adj[b].append(a)

