    for i, sr in enumerate(sep_rows):
        for j in range(C):
            c0 = 0 if j == 0 else sep_cols[j - 1] + 1
            c1 = W - 1 if j == len(sep_cols) else sep_cols[j] - 1
            open_gap = any(grid[sr][c] == 0 for c in range(c0, c1 + 1))
            if open_gap:
                a = cell_id(i, j)
                b = cell_id(i + 1, j)
                adj[a].append(b)
                adj[b].append(a)

    # Components and their sizes in number of cells
    comp = [-1] * n
    comp_size = []
    cid = 0
    for s in range(n):
        if comp[s] != -1:
            continue
        stack = [s]
        comp[s] = cid
