            if r not in row_set and c not in col_set:
                i = row_band(r)
                j = col_band(c)
                out[r][c] = color_for_cell(i, j)

            # Gap on horizontal separator
            elif r in row_set and c not in col_set:
                i_down = sep_rows.index(r)
                j = col_band(c)
                out[r][c] = color_for_cell(i_down, j)

            # Gap on vertical separator
            elif r not in row_set and c in col_set:
                i = row_band(r)
                j_right = sep_cols.index(c)
                out[r][c] = color_for_cell(i, j_right)

            # Rare intersection gap: use a neighboring cell if possible
            else:
                candidates = []
                ir = sep_rows.index(r)
                jc = sep_cols.index(c)
                if ir >= 0 and jc >= 0:
                    if ir < R and jc < C:
                        candidates.append((ir, jc))
                    if ir < R and jc + 1 < C:
