                        candidates.append((ir + 1, jc))
                    if ir + 1 < R and jc + 1 < C:
                        candidates.append((ir + 1, jc + 1))
                if candidates:
                    i, j = candidates[0]
                    out[r][c] = color_for_cell(i, j)
                else:
                    out[r][c] = 3

